gRa(){return"\u0418\u043a\u043e\u043d\u043a\u0430 \u0433\u0440\u0443\u043f\u043f\u044b"},
ga3l(){return"\u0415\u0451 \u0432\u0438\u0434\u044f\u0442 \u0432\u0441\u0435 \u0432 \u0433\u0440\u0443\u043f\u043f\u0435. \u0421\u0442\u0430\u0432\u0438\u0442\u0441\u044f \u0441\u0440\u0430\u0437\u0443, \u0431\u0435\u0437 \xab\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c\xbb"},
