gaoZ(){return"\u0413\u0440\u0443\u043f\u043f\u0430 \u0437\u0430\u0448\u0438\u0444\u0440\u043e\u0432\u0430\u043d\u0430: \u043a\u043b\u044e\u0447 \u0445\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430\u0445 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432, \u0441\u0435\u0440\u0432\u0435\u0440 \u0435\u0433\u043e \u043d\u0435 \u0437\u043d\u0430\u0435\u0442. \u0421\u044e\u0434\u0430 \u043e\u043d \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u0432\u043c\u0435\u0441\u0442\u0435 \u0441\u043e \u0441\u0441\u044b\u043b\u043a\u043e\u0439-\u043f\u0440\u0438\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435\u043c \u044d\u0442\u043e\u0439 \u0433\u0440\u0443\u043f\u043f\u044b."},
gaoS(){return"\u041d\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435, \u0433\u0434\u0435 \u0433\u0440\u0443\u043f\u043f\u0430 \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442\u0441\u044f, \u0437\u0430\u0439\u0434\u0438 \u0432 \u043c\u0435\u043d\u044e \u0433\u0440\u0443\u043f\u043f\u044b \u2192 \xab\u041f\u0440\u0438\u0433\u043b\u0430\u0441\u0438\u0442\u044c \u0434\u0440\u0443\u0437\u0435\u0439\xbb \u2192 \xab\u0421\u0434\u0435\u043b\u0430\u0442\u044c \u0441\u0441\u044b\u043b\u043a\u0443\xbb."},
gaoT(){return"\u041e\u0442\u043a\u0440\u043e\u0439 \u044d\u0442\u0443 \u0441\u0441\u044b\u043b\u043a\u0443 \u0437\u0434\u0435\u0441\u044c \u2014 \u0438\u043b\u0438 \u043d\u0430\u0436\u043c\u0438 \xab\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u0441\u0441\u044b\u043b\u043a\u0443\xbb \u043d\u0438\u0436\u0435 \u0438 \u0432\u0441\u0442\u0430\u0432\u044c \u0435\u0451 \u043b\u0438\u0431\u043e \u043e\u0442\u0441\u043a\u0430\u043d\u0438\u0440\u0443\u0439 QR-\u043a\u043e\u0434."},
gaoU(){return"\u041f\u043e\u043f\u0440\u043e\u0441\u0438 \u0445\u043e\u0441\u0442\u0430 \u0433\u0440\u0443\u043f\u043f\u044b \u043f\u0440\u0438\u0441\u043b\u0430\u0442\u044c \u043d\u043e\u0432\u0443\u044e \u0441\u0441\u044b\u043b\u043a\u0443-\u043f\u0440\u0438\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435."},
