gakj(){return"\u0422\u044b \u0432\u044b\u0439\u0434\u0435\u0448\u044c \u0438\u0437 \u0432\u0441\u0435\u0445 \u0433\u0440\u0443\u043f\u043f. \u0413\u0440\u0443\u043f\u043f\u044b, \u0433\u0434\u0435 \u0442\u044b \u0445\u043e\u0441\u0442, \u043f\u0435\u0440\u0435\u0439\u0434\u0443\u0442 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0443 \u0441 \u043d\u0430\u0438\u0431\u043e\u043b\u044c\u0448\u0435\u0439 REP\u0443\u0442\u0430\u0446\u0438\u0435\u0439. \u0422\u0432\u043e\u0438 REP\u043e\u0440\u0442\u044b \u043e\u0441\u0442\u0430\u043d\u0443\u0442\u0441\u044f \u0432 \u0433\u0440\u0443\u043f\u043f\u0430\u0445, \u043d\u043e \u0431\u0435\u0437 \u0442\u0432\u043e\u0435\u0433\u043e \u0438\u043c\u0435\u043d\u0438. \u0418\u043c\u044f, \u0444\u043e\u0442\u043e, \u043f\u043e\u0434\u043f\u0438\u0441\u043a\u0430 \u0438 \u043a\u043b\u044e\u0447\u0438 \u0437\u0430\u0448\u0438\u0444\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0433\u0440\u0443\u043f\u043f \u0443\u0434\u0430\u043b\u044f\u0442\u0441\u044f. \u0412\u0435\u0440\u043d\u0443\u0442\u044c \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u0431\u0443\u0434\u0435\u0442 \u043d\u0435\u043b\u044c\u0437\u044f."},
gakl(){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u043d\u0430\u0432\u0441\u0435\u0433\u0434\u0430"},
